local script=debug.getinfo(1,'S').source:sub(2);local root=script:gsub('[/\\]docs[/\\]tools[/\\]migrate_sk_callers.lua$','');package.path=root..'/?.lua;'..package.path;local path=require('tools.lua.lib.path');local lfs=require('lfs');local stat=path.join(root,'scripts','script-abi','src','stat_keys.rs');local src=path.join(root,'omb','src');local mapping={};for pascal,wire in path.read(stat):gmatch('StatKey::([%w_]+)%s*=>%s*"([a-z0-9_]+)"')do mapping[wire:upper()]=pascal end;print('Loaded '..tostring((function()local n=0;for _ in pairs(mapping)do n=n+1 end;return n end)())..' StatKey mappings.')
local skip={BUFF_ID_STUN=true,BUFF_ID_ROOT=true,BUFF_ID_SILENCE=true,BUFF_ID_INVISIBLE=true,BUFF_ID_INVULNERABLE=true};local total,changed=0,0;local function visit(dir)for name in lfs.dir(dir)do if name~='.'and name~='..'then local file=path.join(dir,name);if lfs.attributes(file,'mode')=='directory'then visit(file)elseif name:match('%.rs$')then local original=path.read(file);local count=0;local function repl(prefix,key,suffix)if skip[key]or not mapping[key]then return prefix..key..suffix end;count=count+1;return'StatKey::'..mapping[key]..(suffix=='.into()'and'.as_str().into()'or'')end;local value=original:gsub('(%f[%w]sk::)([A-Z][A-Z0-9_]+)(%.into%(%))',repl):gsub('(%f[%w]stat_keys::)([A-Z][A-Z0-9_]+)(%.into%(%))',repl):gsub('(%f[%w]sk::)([A-Z][A-Z0-9_]+)(%f[^%w_])',repl):gsub('(%f[%w]stat_keys::)([A-Z][A-Z0-9_]+)(%f[^%w_])',repl);if count>0 then value=value:gsub('use%s+omb_script_abi::stat_keys%s+as%s+sk%s*;','use omb_script_abi::stat_keys::StatKey;');path.write(file,value,true);total=total+count;changed=changed+1;print('  '..file..': '..count..' replacements')end end end end end;visit(src);print(string.format('Done: %d replacements across %d files.',total,changed))
